const offerTexts={"publicTitle": {"sv": "Från insats till ett tydligt nästa steg", "en": "From support to a clear next step", "ar": "من الدعم إلى خطوة تالية واضحة", "so": "Taageero ilaa tallaabo cad", "fa": "از حمایت تا گام بعدی روشن", "uk": "Від підтримки до чіткого наступного кроку"}, "publicLead": {"sv": "Kompass erbjuder avgränsade uppdrag som hjälper kommuner, myndigheter och arbetsmarknadsaktörer att hitta glapp, ta vara på kompetens och följa människor vidare. Med bas i Höga Kusten arbetar vi för hela Sverige.", "en": "Kompass offers defined assignments to help municipalities, authorities and employment providers identify gaps, use skills and follow people through their next steps. Based in the High Coast, serving all of Sweden.", "ar": "تقدم Kompass مهام محددة لمساعدة البلديات والجهات الحكومية ومقدمي خدمات العمل على تحديد الفجوات واستثمار المهارات ومتابعة الخطوات التالية. مقرنا في الساحل العالي ونخدم السويد كلها.", "so": "Kompass waxay bixisaa hawlo qeexan oo ka caawiya degmooyinka iyo hay’adaha inay helaan farqiyada, adeegsadaan xirfadaha oo dadka la socdaan. Xaruntu waa Höga Kusten, adeeggu Iswiidhan oo dhan.", "fa": "Kompass مأموریت‌های مشخص برای شناسایی شکاف‌ها، استفاده از مهارت‌ها و پیگیری مسیر افراد به شهرداری‌ها و نهادها ارائه می‌دهد. مستقر در Höga Kusten برای سراسر سوئد.", "uk": "Kompass пропонує визначені завдання для муніципалітетів, органів влади й служб зайнятості: знайти прогалини, використати навички та супроводити наступні кроки. База в Höga Kusten, робота по всій Швеції."}, "buy": {"sv": "Det här kan ni anlita Kompass för", "en": "What you can commission Kompass to do", "ar": "ما يمكنكم تكليف Kompass به", "so": "Hawlaha aad Kompass u dhiiban kartaan", "fa": "برای چه کاری می‌توانید Kompass را به خدمت بگیرید", "uk": "Що можна замовити в Kompass"}, "map": {"sv": "1. Kartläggning av behov och glapp", "en": "1. Map needs and gaps", "ar": "١. تحديد الاحتياجات والفجوات", "so": "1. Ogaanshaha baahida iyo farqiyada", "fa": "۱. بررسی نیازها و شکاف‌ها", "uk": "1. Аналіз потреб і прогалин"}, "mapBody": {"sv": "När ni har flera insatser men saknar en samlad bild av var människor fastnar. Vi går igenom befintliga arbetssätt, intervjuar överenskomna aktörer och identifierar hinder, överlappningar och behov som inte fångas upp.", "en": "When several services exist but you lack a shared picture of where people get stuck. We review current practices, interview agreed stakeholders and identify obstacles, overlaps and unmet needs.", "ar": "عندما توجد خدمات متعددة دون صورة مشتركة عن مواضع التعثر. نراجع أساليب العمل ونجري مقابلات متفقاً عليها ونحدد العوائق والتداخل والاحتياجات غير الملباة.", "so": "Marka adeegyo badan jiraan balse aan la garan halka dadku ku xannibmaan. Waxaan eegnaa shaqada jirta, wareysannaa dhinacyada oo helnaa caqabadaha iyo baahida maqan.", "fa": "وقتی خدمات متعدد هست اما محل توقف افراد روشن نیست، روش‌های جاری و مصاحبه با طرف‌های توافق‌شده را بررسی و موانع، هم‌پوشانی و نیازهای برآورده‌نشده را مشخص می‌کنیم.", "uk": "Коли послуг багато, але не зрозуміло, де люди застрягають. Аналізуємо практики, проводимо погоджені інтерв’ю, визначаємо перешкоди, дублювання й незадоволені потреби."}, "mapOut": {"sv": "Leverans: nulägesbild, prioriterade glapp och förslag på nästa steg med ansvar och möjliga mått.", "en": "Delivery: current-state summary, priority gaps and proposed next steps with responsibilities and possible measures.", "ar": "المخرجات: صورة للوضع والفجوات ذات الأولوية وخطوات مقترحة بمسؤوليات ومؤشرات محتملة.", "so": "Natiijo: sawirka xaaladda, farqiyada mudnaanta leh iyo tallaabooyin leh masuuliyad iyo cabbir.", "fa": "خروجی: تصویر وضع موجود، شکاف‌های اولویت‌دار و گام‌های پیشنهادی با مسئول و معیار احتمالی.", "uk": "Результат: опис стану, пріоритетні прогалини та наступні кроки з відповідальними й можливими показниками."}, "pilot": {"sv": "2. Avgränsad pilot med deltagare", "en": "2. A defined participant pilot", "ar": "٢. تجربة محددة مع المشاركين", "so": "2. Tijaabo qeexan oo ka qaybgalayaal leh", "fa": "۲. پایلوت محدود با مشارکت‌کنندگان", "uk": "2. Обмежений пілот з учасниками"}, "pilotBody": {"sv": "När ett identifierat glapp behöver prövas i praktiken. För en överenskommen målgrupp kartlägger vi kompetens, prövar vägar mot arbete, utbildning eller företagande och tar fram en individuell nästa-steg-plan. Deltagarunderlag och tillgång till relevanta aktörer måste vara klarlagda före start.", "en": "When an identified gap needs testing in practice. For an agreed group, we map skills, explore work, education or business paths and prepare individual next-step plans. Participant availability and access to relevant partners must be established before starting.", "ar": "عندما تحتاج فجوة محددة إلى اختبار عملي. لمجموعة متفق عليها نحدد المهارات ونستكشف العمل أو التعليم أو المشروع ونعد خططاً فردية. يجب توضيح توفر المشاركين والشركاء قبل البدء.", "so": "Marka farqi la helay u baahan yahay tijaabo. Koox la heshiiyey waxaan u eegnaa xirfadaha, jidka shaqo, waxbarasho ama ganacsi oo samaynaa qorshe qof walba. Ka qaybgalayaasha iyo la-hawlgalayaashu waa inay caddaadaan ka hor bilowga.", "fa": "برای آزمایش عملی شکاف شناسایی‌شده، مهارت‌های گروه توافق‌شده را بررسی و مسیر کار، آموزش یا کسب‌وکار و برنامه فردی تهیه می‌کنیم. وجود شرکت‌کنندگان و دسترسی به همکاران باید پیش از شروع روشن باشد.", "uk": "Для практичної перевірки виявленої прогалини аналізуємо навички погодженої групи, шляхи роботи, навчання чи бізнесу й складаємо індивідуальні плани. Учасники та доступ до партнерів мають бути визначені до початку."}, "pilotOut": {"sv": "Leverans: deltagarnas underlag och planer, genomförda kontakter och en rapport om vad metoden gav och vad som behöver ändras.", "en": "Delivery: participant summaries and plans, completed contacts and a report on outcomes and needed changes.", "ar": "المخرجات: ملخصات وخطط المشاركين والاتصالات المنفذة وتقرير النتائج والتعديلات المطلوبة.", "so": "Natiijo: qorshayaasha dadka, xiriirrada la sameeyey iyo warbixin waxa soo baxay iyo wax laga beddelayo.", "fa": "خروجی: خلاصه و برنامه افراد، تماس‌های انجام‌شده و گزارش نتایج و اصلاحات لازم.", "uk": "Результат: матеріали й плани учасників, здійснені контакти та звіт про результати й необхідні зміни."}, "coord": {"sv": "3. Samordning och uppföljning", "en": "3. Coordination and follow-up", "ar": "٣. التنسيق والمتابعة", "so": "3. Isku-duwid iyo dabagal", "fa": "۳. هماهنگی و پیگیری", "uk": "3. Координація та супровід"}, "coordBody": {"sv": "När människor behöver stöd i övergången mellan verksamheter. Vi samordnar överenskomna kontakter, tydliggör vem som ansvarar för nästa steg och följer upp om den planerade kontakten eller aktiviteten verkligen blev av.", "en": "When people need help moving between services. We coordinate agreed contacts, clarify who owns the next step and follow up whether the planned contact or activity actually happened.", "ar": "عندما يحتاج الناس دعماً بين الجهات، ننسق الاتصالات المتفق عليها ونوضح مسؤولية الخطوة التالية ونتابع تحقق النشاط أو الاتصال.", "so": "Marka dadku u baahan yihiin kala-guurka adeegyada, waxaan isku duwnaa xiriirrada, caddaynaa masuulka oo hubinnaa hawsha inay dhacday.", "fa": "برای کمک به انتقال بین خدمات، تماس‌های توافق‌شده و مسئول گام بعدی را روشن و انجام واقعی فعالیت یا تماس را پیگیری می‌کنیم.", "uk": "Допомагаємо при переході між службами: координуємо погоджені контакти, визначаємо відповідального й перевіряємо, чи запланована дія відбулася."}, "coordOut": {"sv": "Leverans: ansvarsfördelning, kontakt- och uppföljningsplan samt sammanställd status och kvarstående hinder.", "en": "Delivery: responsibilities, contact and follow-up plan, aggregated progress and remaining obstacles.", "ar": "المخرجات: توزيع المسؤوليات وخطة اتصال ومتابعة وملخص التقدم والعوائق.", "so": "Natiijo: masuuliyad, qorshe xiriir iyo dabagal, horumar iyo caqabado haray.", "fa": "خروجی: مسئولیت‌ها، برنامه تماس و پیگیری و وضعیت پیشرفت و موانع باقی‌مانده.", "uk": "Результат: відповідальність, план контактів і супроводу, зведений стан і перешкоди."}, "measure": {"sv": "Resultat som går att följa", "en": "Results you can track", "ar": "نتائج يمكن متابعتها", "so": "Natiijooyin la cabbiri karo", "fa": "نتایج قابل پیگیری", "uk": "Результати, які можна відстежити"}, "measureBody": {"sv": "Vi kommer överens om utgångsläge och uppföljning innan arbetet börjar. Exempel på mått är genomförda kartläggningar, deltagare med en konkret plan, genomförda arbetsgivar- eller utbildningskontakter och övergångar till arbete, utbildning eller betalande kund. Aktivitet och faktisk övergång redovisas var för sig. Jobb eller företagsframgång kan inte garanteras.", "en": "We agree a baseline and follow-up before starting. Measures may include completed assessments, participants with concrete plans, employer or education contacts and transitions to work, education or a paying customer. Activities and actual transitions are reported separately. Jobs or business success cannot be guaranteed.", "ar": "نتفق على خط البداية والمتابعة. تشمل المؤشرات التقييمات والخطط والاتصالات والانتقال إلى عمل أو تعليم أو عميل يدفع. نفرق بين النشاط والانتقال الفعلي. لا نضمن الوظائف أو نجاح المشروع.", "so": "Waxaan heshiinnaa bilowga iyo dabagalka. Cabbirku wuxuu noqon karaa qiimayn, qorshe, xiriir shaqo ama waxbarasho iyo u gudub shaqo, waxbarasho ama macaamil bixiya. Hawl iyo natiijo dhab ah waa kala gaar. Shaqo ama guul lama dammaanad qaado.", "fa": "پیش از شروع، وضع پایه و پیگیری توافق می‌شود. معیارها می‌تواند ارزیابی، برنامه مشخص، تماس کارفرما یا آموزش و انتقال به کار، آموزش یا مشتری پولی باشد. فعالیت و انتقال واقعی جدا گزارش می‌شوند. شغل یا موفقیت تضمین نمی‌شود.", "uk": "Погоджуємо початковий стан і супровід. Показники: оцінювання, конкретні плани, контакти з роботодавцями чи освітою, перехід до роботи, навчання або платного клієнта. Дії й фактичні переходи звітуємо окремо. Роботу чи успіх не гарантуємо."}, "scope": {"sv": "Ett tydligt uppdrag före start", "en": "A clear assignment before starting", "ar": "مهمة واضحة قبل البداية", "so": "Hawl cad ka hor bilowga", "fa": "مأموریت روشن پیش از شروع", "uk": "Чітке завдання перед початком"}, "scopeBody": {"sv": "Först kartlägger vi vad ni redan gör. Därefter preciserar vi målgrupp, antal deltagare, leverans, ansvar, tidsram, uppföljning och pris i ett förslag. Kompass kompletterar befintliga aktörer. Ett större nationellt arbete byggs först när mindre försök ger ett användbart underlag.", "en": "First we understand your existing work. Then we define the group, participant numbers, delivery, responsibilities, timeline, follow-up and price in a proposal. Kompass complements existing providers. Larger national work is built on useful evidence from smaller trials.", "ar": "نفهم أولاً العمل القائم، ثم نحدد المجموعة وعدد المشاركين والمخرجات والمسؤوليات والوقت والمتابعة والسعر بمقترح. نكمل الجهات القائمة ونبني العمل الوطني على تجارب أصغر.", "so": "Marka hore waxaan fahannaa waxa jira, kadib koox, tiro, natiijo, masuuliyad, waqti, dabagal iyo qiime ayaan qeexnaa. Kompass way dhammaystirtaa adeegyada jira. Shaqada qaran waxay ku dhisantaa tijaabo yar.", "fa": "ابتدا کار موجود شما را بررسی، سپس گروه، تعداد، خروجی، مسئولیت، زمان، پیگیری و قیمت را پیشنهاد می‌کنیم. Kompass مکمل طرف‌های موجود است. کار ملی بر شواهد آزمایش کوچک‌تر بنا می‌شود.", "uk": "Спочатку вивчаємо вашу поточну роботу, потім визначаємо групу, кількість, результат, відповідальність, строки, супровід і ціну. Доповнюємо наявних виконавців. Національна робота спирається на результати малих випробувань."}, "discuss": {"sv": "Beskriv ert behov – be om ett första samtal", "en": "Describe your need — request a first conversation", "ar": "صفوا احتياجكم واطلبوا حواراً أولياً", "so": "Sharax baahida oo dalbo wada-hadal", "fa": "نیاز خود را شرح دهید و گفت‌وگوی اولیه بخواهید", "uk": "Опишіть потребу — запросіть першу розмову"}, "businessTitle": {"sv": "Gör din kompetens till ett erbjudande som kunder förstår", "en": "Turn your skills into an offer customers understand", "ar": "حوّل مهاراتك إلى عرض يفهمه العملاء", "so": "Xirfadahaaga ka dhig adeeg macaamiishu fahmaan", "fa": "مهارت خود را به پیشنهادی قابل فهم برای مشتری تبدیل کنید", "uk": "Перетворіть навички на зрозумілу клієнтам пропозицію"}, "businessLead": {"sv": "Kompass hjälper dig att välja målgrupp, pröva efterfrågan och planera vägen till betalande kunder. Du kan anlita oss för ett avgränsat steg eller en överenskommen följd av insatser.", "en": "Kompass helps you choose a customer group, test demand and plan a path to paying customers. Commission a defined step or an agreed sequence of support.", "ar": "نساعدك على اختيار العملاء واختبار الطلب والتخطيط للعملاء الذين يدفعون. يمكنك تكليفنا بخطوة محددة أو سلسلة دعم متفق عليها.", "so": "Waxaan kaa caawinnaa koox macaamiil, tijaabada baahida iyo jidka iibka. Nagu dhiibo tallaabo ama taageero isku xiran.", "fa": "در انتخاب مشتری، آزمایش تقاضا و مسیر مشتری پولی کمک می‌کنیم. یک گام مشخص یا مجموعه حمایت توافق‌شده سفارش دهید.", "uk": "Допомагаємо обрати клієнтів, перевірити попит і спланувати платні продажі. Замовте окремий крок або погоджену послідовність підтримки."}, "idea": {"sv": "Affärsidé och verklighetstest", "en": "Business idea and practical testing", "ar": "فكرة المشروع واختبارها", "so": "Fikradda iyo tijaabada", "fa": "ایده و آزمایش عملی", "uk": "Бізнес-ідея й практична перевірка"}, "ideaBody": {"sv": "Vi konkretiserar vad du säljer, till vem och varför kunden skulle välja dig. Leverans: ett tydligt erbjudande och en plan för att testa det med möjliga kunder.", "en": "We clarify what you sell, to whom and why customers would choose you. Delivery: a clear offer and a plan to test it with potential customers.", "ar": "نوضح ما تبيع ولمن ولماذا يختارك العميل. المخرجات عرض واضح وخطة لاختباره مع العملاء.", "so": "Waxaan caddaynaa waxa la iibiyo, cidda iyo sababta. Natiijo: adeeg cad iyo qorshe tijaabo.", "fa": "چه می‌فروشید، به چه کسی و چرا شما را انتخاب می‌کند روشن می‌کنیم. خروجی: پیشنهاد مشخص و برنامه آزمایش مشتری.", "uk": "Уточнюємо, що продаєте, кому й чому оберуть вас. Результат: чітка пропозиція й план перевірки з клієнтами."}, "start": {"sv": "Startförberedelse och budget", "en": "Start preparation and budget", "ar": "التحضير والميزانية", "so": "Diyaargarow iyo miisaaniyad", "fa": "آماده‌سازی و بودجه", "uk": "Підготовка та бюджет"}, "startBody": {"sv": "Vi går igenom startkostnader, pris, löpande kostnader och frågor om registrering och krav som behöver kontrolleras. Leverans: kalkylunderlag och en prioriterad checklista före start.", "en": "We review start-up costs, pricing, running costs and registration or requirements that need checking. Delivery: a calculation summary and a priority pre-start checklist.", "ar": "نراجع تكاليف البداية والسعر والتكاليف الجارية والتسجيل والمتطلبات. المخرجات حساب وقائمة أولويات قبل البدء.", "so": "Waxaan eegnaa bilowga, qiimaha, kharashyada iyo shuruudaha. Natiijo: xisaab iyo liis mudnaan ka hor bilowga.", "fa": "هزینه شروع، قیمت، هزینه جاری و ثبت و الزامات را مرور می‌کنیم. خروجی: محاسبه و فهرست اولویت پیش از شروع.", "uk": "Розглядаємо витрати початку, ціни, поточні витрати й вимоги. Результат: розрахунок та пріоритетний список перед початком."}, "sales": {"sv": "Kundkontakt och utveckling", "en": "Customer contact and development", "ar": "التواصل مع العملاء والتطوير", "so": "Xiriirka macaamiisha iyo horumar", "fa": "تماس مشتری و توسعه", "uk": "Контакт із клієнтами та розвиток"}, "salesBody": {"sv": "Vi tydliggör erbjudandet, väljer kontaktvägar och planerar hur ni följer upp intresse, offert och köp. Leverans: en genomförbar kundplan med ansvar, nästa kontakter och uppföljningsdatum.", "en": "We clarify the offer, choose contact channels and plan how to follow interest, quotes and sales. Delivery: a workable customer plan with responsibilities, next contacts and follow-up dates.", "ar": "نوضح العرض ونختار قنوات الاتصال ونخطط لمتابعة الاهتمام والعروض والشراء. المخرجات خطة عملاء بمسؤوليات واتصالات وتواريخ.", "so": "Waxaan caddeynaa adeegga, jidka xiriirka iyo dabagalka iibka. Natiijo: qorshe macaamiil, masuul, xiriir iyo taariikh.", "fa": "پیشنهاد و کانال تماس و پیگیری علاقه، قیمت‌گذاری و خرید را مشخص می‌کنیم. خروجی: برنامه مشتری با مسئول، تماس بعدی و تاریخ.", "uk": "Уточнюємо пропозицію, канали й супровід інтересу, пропозицій та купівлі. Результат: план клієнтів, відповідальні, контакти й дати."}, "try": {"sv": "Börja med företagssimulatorn", "en": "Start with the business simulator", "ar": "ابدأ بمحاكي المشروع", "so": "Ku bilow tijaabiyaha ganacsiga", "fa": "با شبیه‌ساز کسب‌وکار شروع کنید", "uk": "Почніть із бізнес-симулятора"}, "request": {"sv": "Be om ett upplägg för ditt behov", "en": "Request an approach for your needs", "ar": "اطلب خطة لاحتياجك", "so": "Dalbo qorshe baahidaada", "fa": "برای نیاز خود طرح بخواهید", "uk": "Запросіть підхід до вашої потреби"}, "workTitle": {"sv": "Ta vara på kompetensen – följ nästa steg hela vägen", "en": "Use skills — follow the next step through", "ar": "استثمر المهارات وتابع الخطوة التالية", "so": "Ka faa’iidayso xirfadaha oo la soco tallaabada", "fa": "از مهارت استفاده کنید و گام بعد را پیگیری کنید", "uk": "Використайте навички й супроводіть наступний крок"}, "workBody": {"sv": "För arbetsgivare, utbildningsaktörer och leverantörer av arbetsmarknadsinsatser kan Kompass bidra med kompetenskartläggning, förberedande samtal och samordnade kontakter. Ett uppdrag kan ge en kompetensprofil, en individuell plan och uppföljning av överenskomna kontakter. Vi börjar med att klargöra målgrupp och uppdrag tillsammans.", "en": "For employers, education providers and employment-service providers, Kompass can contribute skills assessments, preparatory conversations and coordinated contacts. An assignment may deliver a skills profile, individual plan and follow-up of agreed contacts. We begin by defining the group and task together.", "ar": "نقدم لأصحاب العمل والتعليم وخدمات العمل تقييم المهارات وحوارات تحضيرية واتصالات منسقة. قد تشمل المخرجات ملف مهارات وخطة فردية ومتابعة. نحدد المجموعة والمهمة معاً أولاً.", "so": "Shaqo-bixiyeyaasha iyo adeegyada waxbarasho/shaqo waxaan u samayn karnaa qiimaynta xirfadda, wada-hadal iyo xiriir la isku duway. Natiijo: xirfad, qorshe qofeed iyo dabagal. Marka hore hawsha ayaan qeexnaa.", "fa": "برای کارفرما و خدمات آموزش و اشتغال، ارزیابی مهارت، گفت‌وگوی آماده‌سازی و هماهنگی تماس ارائه می‌دهیم. خروجی می‌تواند پروفایل مهارت، برنامه فردی و پیگیری باشد. ابتدا گروه و مأموریت را مشخص می‌کنیم.", "uk": "Для роботодавців, освіти й служб зайнятості: оцінювання навичок, підготовчі розмови й контакти. Результат може включати профіль, індивідуальний план і супровід. Спочатку визначаємо групу й завдання."}, "housingTitle": {"sv": "Boendedialog som leder till användbara beslut", "en": "Housing dialogue that informs useful decisions", "ar": "حوار سكني يدعم قرارات مفيدة", "so": "Wada-hadal guri oo go’aan waxtar leh keena", "fa": "گفت‌وگوی مسکن برای تصمیم کاربردی", "uk": "Діалог щодо житла для корисних рішень"}, "housingBody": {"sv": "För fastighetsaktörer och föreningar kan vi planera och genomföra samtal med boende, sammanställa återkommande frågor och tydliggöra förslag och ansvar. Leverans: ett dokumenterat dialogunderlag och en överenskommen plan för återkoppling. Omfattning och pris bestäms efter en första genomgång.", "en": "For property organisations and associations, we can plan resident conversations, summarise recurring issues and clarify proposals and responsibilities. Delivery: documented dialogue findings and an agreed feedback plan. Scope and price follow an initial review.", "ar": "للجهات العقارية والجمعيات ننظم حوارات السكان ونلخص القضايا والمقترحات والمسؤوليات. المخرجات توثيق وخطة متابعة متفق عليها. الحجم والسعر بعد مراجعة أولية.", "so": "Hay’adaha guryaha iyo ururrada waxaan u samaynaa wada-hadal, isu geynta su’aalaha iyo masuuliyadda. Natiijo: warbixin iyo qorshe jawaab. Baaxad iyo qiime kadib kulan.", "fa": "برای نهادهای املاک و انجمن‌ها گفت‌وگوی ساکنان و جمع‌بندی مسائل و مسئولیت‌ها تهیه می‌کنیم. خروجی مستند و برنامه بازخورد توافق‌شده. دامنه و قیمت پس از بررسی اولیه.", "uk": "Для організацій нерухомості й об’єднань плануємо розмови мешканців, узагальнюємо питання й відповідальність. Результат: матеріали діалогу та план зворотного зв’язку. Обсяг і ціна після огляду."}, "societyTitle": {"sv": "Från lokala resurser till genomförbara möjligheter", "en": "From local resources to workable opportunities", "ar": "من الموارد المحلية إلى فرص قابلة للتنفيذ", "so": "Khayraadka deegaanka ilaa fursado la fulin karo", "fa": "از منابع محلی تا فرصت عملی", "uk": "Від місцевих ресурсів до здійсненних можливостей"}, "societyBody": {"sv": "För kommuner, föreningar och fastighetsaktörer undersöker vi hur kompetens, lokaler och befintliga verksamheter kan mötas kring ett konkret behov. Leverans: resurs- och behovskarta, möjliga samarbeten och förslag på ett avgränsat nästa steg. Målet är att skapa bättre förutsättningar för verksamheter och producerande företag.", "en": "For municipalities, associations and property organisations, we explore how skills, premises and existing activities can meet a specific need. Delivery: a resource and needs map, potential partnerships and a defined next-step proposal. The aim is better conditions for activities and businesses producing goods.", "ar": "نستكشف للبلديات والجمعيات والعقارات ربط المهارات والأماكن والأنشطة باحتياج محدد. المخرجات خريطة موارد واحتياجات وشراكات وخطوة محددة لتحسين ظروف الأنشطة والإنتاج.", "so": "Waxaan eegnaa xirfado, goobo iyo hawlo jira oo baahi daboola. Natiijo: khariidad khayraad iyo baahi, iskaashi iyo tallaabo. Ujeedadu waa xaalad wanaagsan oo hawlo iyo wax-soo-saar.", "fa": "برای شهرداری‌ها و انجمن‌ها پیوند مهارت، مکان و فعالیت موجود با نیاز مشخص را بررسی می‌کنیم. خروجی: نقشه منابع و نیاز، همکاری و گام محدود برای شرایط بهتر فعالیت و تولید.", "uk": "Для муніципалітетів і об’єднань досліджуємо зв’язок навичок, приміщень і діяльності з потребою. Результат: карта ресурсів і потреб, партнери й конкретний крок для кращих умов виробництва."}, "contactTitle": {"sv": "Kontakta Kompass – välj det sätt som fungerar för dig", "en": "Contact Kompass — choose what works for you", "ar": "تواصل مع Kompass بالطريقة المناسبة لك", "so": "La xiriir Kompass sida kugu habboon", "fa": "تماس با Kompass به روش مناسب شما", "uk": "Зв’яжіться з Kompass зручним способом"}, "contactLead": {"sv": "Beskriv ditt behov eller ta med simulatorns underlag. Erik Mohamed är din kontaktperson. Välj webbmejl nedan eller kopiera adress och meddelande.", "en": "Describe your need or bring your simulator summary. Erik Mohamed is your contact person. Choose webmail below or copy the address and message.", "ar": "صف احتياجك أو أرفق ملخص المحاكي. إريك محمد جهة الاتصال. اختر البريد عبر الويب أو انسخ العنوان والرسالة.", "so": "Sharax baahida ama keen natiijada tijaabiyaha. Erik Mohamed ayaa kula xiriiraya. Dooro iimayl web ama koobi cinwaanka iyo farriinta.", "fa": "نیاز یا خلاصه شبیه‌ساز را بیاورید. مسئول تماس اریک محمد است. ایمیل وب یا کپی نشانی و پیام را انتخاب کنید.", "uk": "Опишіть потребу або додайте підсумок симулятора. Контакт — Ерік Мохамед. Оберіть вебпошту чи скопіюйте адресу й повідомлення."}, "subject": {"sv": "Vad gäller din kontakt?", "en": "What is your enquiry about?", "ar": "ما موضوع التواصل؟", "so": "Maxaa xiriirkaagu ku saabsan yahay?", "fa": "موضوع تماس چیست؟", "uk": "Щодо чого звернення?"}, "personal": {"sv": "Arbete, utbildning eller min kompetens", "en": "Work, education or my skills", "ar": "عمل أو تعليم أو مهاراتي", "so": "Shaqo, waxbarasho ama xirfadayda", "fa": "کار، آموزش یا مهارت من", "uk": "Робота, навчання чи мої навички"}, "municipal": {"sv": "Uppdrag för kommun eller organisation", "en": "Assignment for a municipality or organisation", "ar": "مهمة لبلدية أو منظمة", "so": "Hawl degmo ama hay’ad", "fa": "مأموریت شهرداری یا سازمان", "uk": "Завдання муніципалітету чи організації"}, "company": {"sv": "Affärsidé eller företagsutveckling", "en": "Business idea or business development", "ar": "فكرة أو تطوير مشروع", "so": "Fikrad ama horumar ganacsi", "fa": "ایده یا توسعه کسب‌وکار", "uk": "Бізнес-ідея чи розвиток"}, "message": {"sv": "Ditt meddelande / underlag", "en": "Your message / summary", "ar": "رسالتك / ملخصك", "so": "Farriintaada / qorshaha", "fa": "پیام / خلاصه شما", "uk": "Ваше повідомлення / підсумок"}, "placeholder": {"sv": "Beskriv vad du vill ha hjälp med. Lägg gärna till namn, ort och önskat kontaktsätt.", "en": "Describe the help you need. You may add your name, location and preferred contact method.", "ar": "صف المساعدة المطلوبة. يمكنك إضافة الاسم والمكان وطريقة الاتصال.", "so": "Sharax caawinta. Ku dar magac, goob iyo sida laguu soo xiriiro.", "fa": "کمک مورد نیاز را شرح دهید. نام، محل و روش تماس دلخواه را اضافه کنید.", "uk": "Опишіть потрібну допомогу. Можна додати ім’я, місце й спосіб зв’язку."}, "gmail": {"sv": "Öppna i Gmail", "en": "Open in Gmail", "ar": "افتح في Gmail", "so": "Ku fur Gmail", "fa": "باز کردن در Gmail", "uk": "Відкрити в Gmail"}, "outlook": {"sv": "Öppna i Outlook", "en": "Open in Outlook", "ar": "افتح في Outlook", "so": "Ku fur Outlook", "fa": "باز کردن در Outlook", "uk": "Відкрити в Outlook"}, "app": {"sv": "Öppna annat mejlprogram", "en": "Open another email app", "ar": "افتح برنامج بريد آخر", "so": "Fur iimayl kale", "fa": "باز کردن برنامه ایمیل دیگر", "uk": "Відкрити іншу поштову програму"}, "copyEmail": {"sv": "Kopiera e-postadressen", "en": "Copy email address", "ar": "انسخ عنوان البريد", "so": "Koobi cinwaanka iimaylka", "fa": "کپی نشانی ایمیل", "uk": "Скопіювати адресу пошти"}, "copyMessage": {"sv": "Kopiera meddelandet", "en": "Copy message", "ar": "انسخ الرسالة", "so": "Koobi farriinta", "fa": "کپی پیام", "uk": "Скопіювати повідомлення"}, "phone": {"sv": "Ring Erik: 073-777 36 66", "en": "Call Erik: 073-777 36 66", "ar": "اتصل بإريك: 073-777 36 66", "so": "Wac Erik: 073-777 36 66", "fa": "تماس با اریک: 073-777 36 66", "uk": "Телефон Еріку: 073-777 36 66"}, "sendNote": {"sv": "Du granskar och skickar själv i din mejltjänst. Inget skickas från den här sidan. Du kan behöva logga in i Gmail eller Outlook. Skicka inte känsliga personuppgifter.", "en": "You review and send in your email service. Nothing is sent from this page. Gmail or Outlook may require sign-in. Do not send sensitive personal data.", "ar": "تراجع وترسل بنفسك عبر البريد. لا تُرسل هذه الصفحة شيئاً. قد يلزم تسجيل الدخول. لا ترسل بيانات شخصية حساسة.", "so": "Adiga ayaa hubiya oo dira. Boggan wax ma diro. Gmail ama Outlook waxaa laga yaabaa inaad gasho. Ha dirin xog xasaasi ah.", "fa": "خودتان در سرویس ایمیل بررسی و ارسال می‌کنید. این صفحه چیزی نمی‌فرستد. شاید ورود لازم باشد. داده حساس نفرستید.", "uk": "Перевіряєте й надсилаєте самі у пошті. Ця сторінка нічого не надсилає. Можливо, треба увійти. Не надсилайте чутливих даних."}, "copied": {"sv": "Kopierat. Klistra in i ditt mejl.", "en": "Copied. Paste into your email.", "ar": "تم النسخ. الصقه في بريدك.", "so": "La koobiyeeyey. Ku dheji iimaylka.", "fa": "کپی شد. در ایمیل بچسبانید.", "uk": "Скопійовано. Вставте в пошту."}, "fallback": {"sv": "Markera texten och kopiera manuellt.", "en": "Select the text and copy manually.", "ar": "حدد النص وانسخه يدوياً.", "so": "Dooro qoraalka oo gacanta ku koobi.", "fa": "متن را دستی انتخاب و کپی کنید.", "uk": "Виділіть текст і скопіюйте вручну."}, "price": {"sv": "Omfattning och pris efter behov", "en": "Scope and price based on need", "ar": "الحجم والسعر وفق الحاجة", "so": "Baaxad iyo qiime baahida ku salaysan", "fa": "دامنه و قیمت بر اساس نیاز", "uk": "Обсяг і ціна відповідно до потреби"}, "priceBody": {"sv": "Vi föreslår ett avgränsat upplägg med tydlig leverans och kostnad efter en första dialog. Ingen beställning görs genom att du använder simulatorn eller kontaktar oss.", "en": "After an initial conversation we propose a defined approach with clear deliverables and cost. Using the simulator or contacting us does not place an order.", "ar": "بعد حوار أولي نقترح خطة محددة بمخرجات وتكلفة واضحة. استخدام المحاكي أو التواصل ليس طلب شراء.", "so": "Kadib wada-hadal waxaan soo jeedinaynaa qorshe iyo kharash cad. Tijaabiyaha ama xiriirku ma aha dalab iibsasho.", "fa": "پس از گفت‌وگو طرح محدود با خروجی و هزینه روشن پیشنهاد می‌کنیم. استفاده از شبیه‌ساز یا تماس سفارش نیست.", "uk": "Після розмови пропонуємо визначений підхід із результатом і вартістю. Симулятор або звернення не є замовленням."}};
(()=>{
 const root=document.getElementById('kompass-preview');if(!root)return;
 const picker=root.querySelector('#kompass-language-select');const lang=()=>picker.value;const t=k=>offerTexts[k][lang()];const email='erikdeenson@gmail.com';let draft='';try{draft=sessionStorage.getItem('kompassContactDraft')||'';}catch{}
 const node=(tag,key)=>{const e=document.createElement(tag);if(key)e.textContent=t(key);return e;};
 function link(key,url){const a=node('a',key);a.href=url;a.className='action';return a;}
 function card(title,body,out){const c=node('article');c.className='audience';c.append(node('h3',title),node('p',body));if(out)c.append(node('p',out));return c;}
 function commonPrice(host){host.append(node('h3','price'),node('p','priceBody'));}
 function business(host){const image=host.id==='detail-utveckling'?host.querySelector('img'):null;host.replaceChildren();if(image)host.append(image);host.append(node('h2','businessTitle'),node('p','businessLead'));const grid=node('div');grid.className='grid';grid.append(card('idea','ideaBody'),card('start','startBody'),card('sales','salesBody'));host.append(grid);commonPrice(host);const actions=node('div');actions.className='actions';actions.append(link('try','starta-foretag.html?lang='+lang()),link('request','kontakta-oss.html?lang='+lang()));host.append(actions);}
 function municipal(host){host.replaceChildren(node('h2','publicTitle'),node('p','publicLead'),node('h3','buy'));const grid=node('div');grid.className='grid';grid.append(card('map','mapBody','mapOut'),card('pilot','pilotBody','pilotOut'),card('coord','coordBody','coordOut'));host.append(grid,node('h3','measure'),node('p','measureBody'),node('h3','scope'),node('p','scopeBody'),link('discuss','kontakta-oss.html?lang='+lang()));}
 async function copy(text,status){try{await navigator.clipboard.writeText(text);status.textContent=t('copied');}catch{const input=node('textarea');input.value=text;status.replaceChildren(document.createTextNode(t('fallback')),input);input.focus();input.select();}}
 function contact(host){host.replaceChildren(node('h2','contactTitle'),node('p','contactLead'));const address=node('p');address.textContent=email;host.append(address);const status=node('p');status.setAttribute('role','status');
 const subjectLabel=node('label','subject');subjectLabel.htmlFor='contact-topic';const subject=node('select');subject.id='contact-topic';for(const key of ['personal','company','municipal']){const o=node('option',key);o.value=key;subject.append(o);}const bodyLabel=node('label','message');bodyLabel.htmlFor='contact-message';const body=node('textarea');body.id='contact-message';body.rows=10;body.placeholder=t('placeholder');body.value=draft;host.append(subjectLabel,subject,bodyLabel,body);
 const actions=node('div');actions.className='actions';const gmail=link('gmail','#'),outlook=link('outlook','#'),app=link('app','#');for(const a of [gmail,outlook]){a.target='_blank';a.rel='noopener';}function update(){draft=body.value;const title='Kompass – '+t(subject.value);gmail.href='https://mail.google.com/mail/?view=cm&fs=1&to='+encodeURIComponent(email)+'&su='+encodeURIComponent(title)+'&body='+encodeURIComponent(draft);outlook.href='https://outlook.live.com/mail/0/deeplink/compose?to='+encodeURIComponent(email)+'&subject='+encodeURIComponent(title)+'&body='+encodeURIComponent(draft);app.href='mailto:'+email+'?subject='+encodeURIComponent(title)+'&body='+encodeURIComponent(draft);app.dataset.nativeMail='true';try{sessionStorage.setItem('kompassContactDraft',draft);}catch{}}
 body.addEventListener('input',update);subject.addEventListener('change',update);update();actions.append(gmail,outlook,app);for(const [key,value] of [['copyEmail',()=>email],['copyMessage',()=>body.value]]){const b=node('button',key);b.className='action secondary';b.type='button';b.addEventListener('click',()=>copy(value(),status));actions.append(b);}host.append(actions,node('p','sendNote'),status,link('phone','tel:+46737773666'));}
 function render(){for(const [id,fn] of [['kompass-partners',municipal],['kompass-utveckling',business],['detail-utveckling',business],['kompass-contact',contact]]){const h=root.querySelector('#'+id);if(h){if(id==='kompass-partners')h.classList.remove('partner');fn(h);}}
 for(const [id,title,body] of [['detail-etablering','workTitle','workBody'],['detail-boende','housingTitle','housingBody'],['detail-hallbart','societyTitle','societyBody']]){const h=root.querySelector('#'+id);if(!h)continue;const img=h.querySelector('img');h.replaceChildren();if(img)h.append(img);h.append(node('h2',title),node('p',body));commonPrice(h);h.append(link('request','kontakta-oss.html?lang='+lang()));}
 const intro=root.querySelector('#kompass-startaeget');const wizard=root.querySelector('#business-wizard');if(wizard&&intro){const page=intro.parentElement;page.append(intro);}}
 const css=node('style');css.textContent='#kompass-preview #kompass-contact label{display:block;margin:20px 0 7px;font-weight:600}#kompass-preview #kompass-contact select,#kompass-preview #kompass-contact textarea{box-sizing:border-box;width:100%;padding:12px;border:1px solid #93aaa6;border-radius:5px;font:inherit;font-size:16px;background:white;color:#183347}#kompass-preview #kompass-partners .audience p{color:#183347}#kompass-preview .action{cursor:pointer}';document.head.append(css);
 picker.addEventListener('change',render);root.addEventListener('click',e=>{const a=e.target.closest('a');if(!a||a.dataset.nativeMail)return;const href=a.getAttribute('href')||'';if(href.startsWith('mailto:')){e.preventDefault();const q=href.split('?')[1]||'';draft=new URLSearchParams(q).get('body')||'';try{sessionStorage.setItem('kompassContactDraft',draft);}catch{}location.href='kontakta-oss.html?lang='+lang();}});render();
})();

const rustaTexts={"nav": {"sv": "Rusta och matcha", "en": "Rusta och matcha", "ar": "Rusta och matcha", "so": "Rusta och matcha", "fa": "Rusta och matcha", "uk": "Rusta och matcha"}, "badge": {"sv": "Gratis vägledning från Kompass", "en": "Free guidance from Kompass", "ar": "إرشاد مجاني من Kompass", "so": "Hagid bilaash ah oo Kompass bixiso", "fa": "راهنمایی رایگان Kompass", "uk": "Безкоштовна консультація Kompass"}, "title": {"sv": "Rusta och matcha – välj stöd som passar din väg framåt", "en": "Rusta och matcha — choose support that fits your path", "ar": "Rusta och matcha — اختر دعماً يناسب طريقك", "so": "Rusta och matcha — dooro taageero ku habboon jidkaaga", "fa": "Rusta och matcha — حمایت مناسب مسیر خود را انتخاب کنید", "uk": "Rusta och matcha — оберіть підтримку для свого шляху"}, "lead": {"sv": "Det kan vara svårt att veta vilken leverantör och vilket kontor som passar dig. Kompass hjälper dig att jämföra alternativen utifrån din kompetens, dina mål och det stöd du behöver för att komma vidare till arbete eller utbildning. Vår vägledning inför valet är gratis.", "en": "It can be hard to know which provider and office fits you. Kompass helps compare options based on your skills, goals and the support you need to move towards work or education. Our guidance before your choice is free.", "ar": "قد يصعب معرفة مقدم الخدمة والمكتب الأنسب. تساعدك Kompass في مقارنة الخيارات حسب مهاراتك وأهدافك والدعم اللازم للعمل أو التعليم. إرشادنا قبل الاختيار مجاني.", "so": "Way adkaan kartaa inaad ogaato adeeg-bixiyaha iyo xafiiska kugu habboon. Kompass waxay kaa caawisaa isbarbardhigga iyadoo eegaysa xirfadda, yoolka iyo taageerada shaqo ama waxbarasho. Hagidda doorashada waa bilaash.", "fa": "انتخاب ارائه‌دهنده و دفتر مناسب دشوار است. Kompass گزینه‌ها را بر اساس مهارت، هدف و حمایت لازم برای کار یا آموزش مقایسه می‌کند. راهنمایی ما پیش از انتخاب رایگان است.", "uk": "Важко визначити відповідного виконавця й офіс. Kompass допомагає порівняти варіанти з урахуванням навичок, цілей і потрібної підтримки для роботи чи навчання. Консультація перед вибором безкоштовна."}, "cta": {"sv": "Hjälp mig att jämföra kontor – gratis", "en": "Help me compare offices — free", "ar": "ساعدني في مقارنة المكاتب مجاناً", "so": "Iga caawi isbarbardhigga xafiisyada — bilaash", "fa": "برای مقایسه دفترها کمک می‌خواهم — رایگان", "uk": "Допоможіть порівняти офіси — безкоштовно"}, "whoTitle": {"sv": "För dig som ska välja eller vill se över ditt val", "en": "For people choosing or reviewing their choice", "ar": "لمن سيختار أو يراجع اختياره", "so": "Qofka dooranaya ama eegaya doorashadiisa", "fa": "برای انتخاب یا بازبینی انتخاب", "uk": "Для тих, хто обирає або переглядає свій вибір"}, "whoBody": {"sv": "Har du fått besked om Rusta och matcha, blivit osäker inför valet eller känner att stödet på ditt nuvarande kontor inte passar? Vi kan hjälpa dig att tydliggöra dina behov och förbereda frågor till leverantören. Om du ännu inte vet om insatsen är aktuell för dig hjälper vi dig att förstå vilka frågor du behöver ta vidare till Arbetsförmedlingen.", "en": "Have you been told about Rusta och matcha, feel unsure about your choice or find your current office does not fit? We can help clarify your needs and prepare questions for the provider. If you do not yet know whether the service applies to you, we help identify questions for Arbetsförmedlingen.", "ar": "هل تلقيت معلومات عن البرنامج أو ترددت في الاختيار أو لا يناسبك مكتبك الحالي؟ نساعدك على توضيح احتياجاتك وإعداد أسئلة لمقدم الخدمة. إن لم تعرف مدى أهليتك نحدد معك الأسئلة التي تطرحها على Arbetsförmedlingen.", "so": "Ma laguu sheegay barnaamijka, ma hubtid doorashada ama xafiiskaagu kuma habboona? Waxaan caddaynnaa baahida oo diyaarinnaa su’aalo. Haddii aadan ogayn inuu barnaamijku ku khuseeyo, waxaan kuu diyaarinnaa su’aalaha Arbetsförmedlingen.", "fa": "درباره برنامه اطلاع گرفته‌اید، در انتخاب تردید دارید یا دفتر فعلی مناسب نیست؟ نیاز و پرسش‌ها را روشن می‌کنیم. اگر نمی‌دانید این خدمت برای شماست، پرسش‌های لازم برای Arbetsförmedlingen را مشخص می‌کنیم.", "uk": "Вам запропонували програму, ви вагаєтеся або нинішній офіс не підходить? Допоможемо визначити потреби й питання до виконавця. Якщо участь ще не визначена, підготуємо питання до Arbetsförmedlingen."}, "helpTitle": {"sv": "Vad hjälper vi dig med?", "en": "How do we help?", "ar": "كيف نساعدك؟", "so": "Maxaan kaa caawinnaa?", "fa": "چگونه کمک می‌کنیم؟", "uk": "Чим допомагаємо?"}, "needs": {"sv": "Din kompetens och ditt mål", "en": "Your skills and goal", "ar": "مهاراتك وهدفك", "so": "Xirfaddaada iyo yoolkaaga", "fa": "مهارت و هدف شما", "uk": "Ваші навички та мета"}, "needsBody": {"sv": "Vi går igenom erfarenhet, utbildning och vad du vill arbeta med. Behöver du stöd med språk, yrkesväxling, jobbsökande eller en väg till utbildning? Det blir grunden för jämförelsen.", "en": "We review your experience, education and desired work. Do you need language support, a career change, job-search help or a path to education? This forms the basis for comparison.", "ar": "نراجع خبرتك وتعليمك والعمل المطلوب. هل تحتاج لغة أو تغيير مهنة أو بحثاً عن عمل أو تعليماً؟ هذا أساس المقارنة.", "so": "Waxaan eegnaa khibrad, waxbarasho iyo shaqada aad rabto. Ma u baahan tahay luqad, beddel xirfad, raadinta shaqo ama waxbarasho? Taas ayaan ku salaynnaa isbarbardhigga.", "fa": "تجربه، آموزش و کار دلخواه را بررسی می‌کنیم. حمایت زبانی، تغییر حرفه، جست‌وجوی کار یا مسیر آموزش نیاز دارید؟ این پایه مقایسه است.", "uk": "Розглянемо досвід, освіту й бажану роботу. Потрібна мовна підтримка, зміна професії, пошук роботи чи навчання? Це основа порівняння."}, "compare": {"sv": "Kontor som är praktiskt möjliga för dig", "en": "Offices that are practical for you", "ar": "مكاتب مناسبة عملياً لك", "so": "Xafiisyo aad adeegsan karto", "fa": "دفترهای قابل دسترس برای شما", "uk": "Офіси, практично доступні вам"}, "compareBody": {"sv": "Vi hjälper dig att undersöka alternativ i ditt område och jämföra yrkesinriktning, språkstöd, tillgänglighet och resväg. Vi tittar på den information som finns och vilka uppgifter som behöver bekräftas direkt med kontoret.", "en": "We help explore local options and compare occupational focus, language support, accessibility and travel. We review available information and identify details to confirm directly with the office.", "ar": "نستكشف خيارات منطقتك ونقارن التخصص واللغة والإتاحة والتنقل. نراجع المعلومات المتاحة وما يحتاج تأكيداً من المكتب.", "so": "Waxaan baadhnaa xafiisyada deegaanka, xirfadaha ay taageeraan, luqad, helitaan iyo safar. Waxaan eegnaa xogta jirta iyo waxa xafiisku xaqiijinayo.", "fa": "گزینه‌های منطقه، تمرکز شغلی، زبان، دسترسی و رفت‌وآمد را مقایسه می‌کنیم. اطلاعات موجود و موارد نیازمند تأیید دفتر را مشخص می‌کنیم.", "uk": "Дослідимо місцеві варіанти, професійний напрям, мовну підтримку, доступність і дорогу. Визначимо наявні дані й те, що треба підтвердити в офісі."}, "questions": {"sv": "Rätt frågor före ditt val", "en": "Useful questions before choosing", "ar": "أسئلة مناسبة قبل الاختيار", "so": "Su’aalo sax ah ka hor doorashada", "fa": "پرسش‌های مناسب پیش از انتخاب", "uk": "Корисні питання перед вибором"}, "questionsBody": {"sv": "Du får hjälp att fråga hur handledningen ska se ut, vilka relevanta arbetsgivarkontakter kontoret har och hur planen följs upp. Betyg och tidigare resultat kan vara ett underlag, men säger inte ensamma vilket kontor som passar just dig.", "en": "We help ask how guidance will work, which relevant employer contacts the office has and how the plan is followed up. Ratings and past results can inform the choice but do not alone establish which office fits you.", "ar": "نساعدك على السؤال عن الإرشاد واتصالات أصحاب العمل والمتابعة. التقييمات والنتائج السابقة تفيد لكنها لا تحدد وحدها المكتب المناسب لك.", "so": "Waxaan diyaarinaynaa su’aalaha hagidda, xiriirka shaqo-bixiyeyaasha iyo dabagalka. Qiimayn iyo natiijo hore way caawiyaan balse keligood ma doortaan xafiiska.", "fa": "برای روش راهنمایی، ارتباط کارفرما و پیگیری سؤال تهیه می‌کنیم. امتیاز و نتیجه گذشته مفید است اما به‌تنهایی تناسب دفتر را تعیین نمی‌کند.", "uk": "Допоможемо запитати про супровід, контакти роботодавців і виконання плану. Оцінки й попередні результати корисні, але не визначають самі відповідний офіс."}, "processTitle": {"sv": "Så går den kostnadsfria vägledningen till", "en": "How the free guidance works", "ar": "كيف يعمل الإرشاد المجاني", "so": "Sida hagidda bilaashku u shaqayso", "fa": "راهنمایی رایگان چگونه انجام می‌شود", "uk": "Як працює безкоштовна консультація"}, "step1": {"sv": "1. Du berättar kort om din situation", "en": "1. Briefly describe your situation", "ar": "١. صف وضعك باختصار", "so": "1. Sharax xaaladdaada", "fa": "۱. وضعیت خود را کوتاه بگویید", "uk": "1. Коротко опишіть ситуацію"}, "step1Body": {"sv": "Ange gärna din ort, önskat yrkesområde och om du redan har ett beslut eller ett kontor. Du behöver inte skicka personnummer, medicinska uppgifter eller andra känsliga uppgifter.", "en": "You may give your location, preferred occupation and whether you already have a decision or office. You do not need to send identity numbers, medical details or other sensitive data.", "ar": "اذكر المكان والمهنة المطلوبة وهل لديك قرار أو مكتب. لا تحتاج إرسال رقم الهوية أو معلومات طبية أو بيانات حساسة.", "so": "Sheeg goobta, xirfadda iyo haddii go’aan ama xafiis jiro. Ha dirin lambar aqoonsi, xog caafimaad ama xog xasaasi ah.", "fa": "محل، حرفه دلخواه و داشتن تصمیم یا دفتر را بگویید. شماره هویت، اطلاعات پزشکی یا داده حساس لازم نیست.", "uk": "Можна вказати місце, професію й наявність рішення чи офісу. Ідентифікаційні номери, медичні чи інші чутливі дані не потрібні."}, "step2": {"sv": "2. Vi går igenom dina behov och alternativ", "en": "2. We review your needs and options", "ar": "٢. نراجع احتياجاتك وخياراتك", "so": "2. Waxaan eegnaa baahida iyo xulashooyinka", "fa": "۲. نیاز و گزینه‌ها را بررسی می‌کنیم", "uk": "2. Розглядаємо потреби й варіанти"}, "step2Body": {"sv": "Tillsammans gör vi en enkel jämförelse och en frågelista att använda i kontakten med kontoren. Uppgifter som saknas markeras som frågor att kontrollera, inte som säkra svar.", "en": "Together we prepare a simple comparison and questions for offices. Missing information is marked for checking, rather than presented as certain.", "ar": "نعد مقارنة بسيطة وأسئلة للمكاتب. المعلومات الناقصة نحددها للتحقق ولا نقدمها كحقائق مؤكدة.", "so": "Waxaan samaynaa isbarbardhig iyo su’aalo. Xogta maqan waxay noqotaa wax la hubinayo, ma aha jawaab la hubo.", "fa": "مقایسه ساده و پرسش‌های دفتر تهیه می‌کنیم. داده ناقص برای بررسی مشخص می‌شود، نه پاسخ قطعی.", "uk": "Готуємо просте порівняння й питання. Відсутні дані позначаємо для перевірки, а не як достовірні відповіді."}, "step3": {"sv": "3. Du väljer själv och tar nästa kontakt", "en": "3. You choose and make the next contact", "ar": "٣. تختار بنفسك وتتواصل", "so": "3. Adiga ayaa doorta oo xiriira", "fa": "۳. خودتان انتخاب و تماس می‌گیرید", "uk": "3. Обираєте самі й контактуєте"}, "step3Body": {"sv": "Målet är att du ska ha ett tydligare underlag för ditt eget val och veta vad du ska fråga efter på det första mötet. Vi hjälper dig att förbereda kontakten; valet av leverantör gör du själv.", "en": "The goal is clearer information for your own choice and knowing what to ask at the first meeting. We help prepare the contact; you choose the provider yourself.", "ar": "الهدف أساس أوضح لاختيارك ومعرفة أسئلة اللقاء الأول. نساعدك على التحضير وأنت تختار مقدم الخدمة.", "so": "Ujeedadu waa xog cad iyo su’aalaha kulanka koowaad. Waxaan diyaarinaynaa xiriirka; adiga ayaa adeeg-bixiyaha doorta.", "fa": "هدف، پایه روشن‌تر برای انتخاب و پرسش‌های دیدار اول است. در آماده‌سازی کمک می‌کنیم؛ ارائه‌دهنده را خودتان برمی‌گزینید.", "uk": "Мета — зрозуміліша основа для вибору й питання першої зустрічі. Допомагаємо підготувати контакт; виконавця обираєте ви."}, "askTitle": {"sv": "Frågor att ta med till kontoret", "en": "Questions to bring to the office", "ar": "أسئلة للمكتب", "so": "Su’aalo aad xafiiska u qaadato", "fa": "پرسش‌هایی برای دفتر", "uk": "Питання до офісу"}, "q1": {"sv": "Vilken erfarenhet har ni av mitt yrkesområde och mina mål?", "en": "What experience do you have with my occupation and goals?", "ar": "ما خبرتكم بمجال مهنتي وأهدافي؟", "so": "Maxay tahay khibraddiinna xirfaddayda iyo yoolkayga?", "fa": "چه تجربه‌ای در حرفه و اهداف من دارید؟", "uk": "Який досвід маєте щодо моєї професії й цілей?"}, "q2": {"sv": "Vem blir min handledare och hur anpassas planen till mig?", "en": "Who will guide me and how is the plan adapted to me?", "ar": "من سيُرشدني وكيف تُكيّف الخطة لي؟", "so": "Yaa i hagaya, sideese qorshaha la iigu habaynayaa?", "fa": "راهنمای من کیست و برنامه چطور برایم تنظیم می‌شود؟", "uk": "Хто мене супроводжуватиме і як адаптуєте план?"}, "q3": {"sv": "Vilka konkreta kontakter och aktiviteter kan ni hjälpa mig med?", "en": "Which specific contacts and activities can you help with?", "ar": "ما الاتصالات والأنشطة المحددة التي تساعدونني بها؟", "so": "Xiriir iyo hawlo noocee ah ayaad iga caawin kartaan?", "fa": "در چه تماس‌ها و فعالیت‌های مشخص کمک می‌کنید؟", "uk": "З якими конкретними контактами й діями допоможете?"}, "q4": {"sv": "Hur följer vi upp att jag faktiskt kommer vidare?", "en": "How do we track real progress?", "ar": "كيف نتابع تقدمي الفعلي؟", "so": "Sidee loo hubiyaa horumarkayga dhabta ah?", "fa": "پیشرفت واقعی را چگونه پیگیری می‌کنیم؟", "uk": "Як відстежимо фактичний прогрес?"}, "roleTitle": {"sv": "Gratis hjälp med jämförelsen – du behåller valet", "en": "Free help comparing — you keep the choice", "ar": "مقارنة مجانية والاختيار لك", "so": "Isbarbardhig bilaash ah — doorashadu adigay kuu taal", "fa": "مقایسه رایگان — انتخاب با شماست", "uk": "Безкоштовне порівняння — вибір за вами"}, "roleBody": {"sv": "Kompass tar inte betalt av dig för denna vägledning. Arbetsförmedlingen bedömer och beslutar om ditt deltagande i Rusta och matcha. Vår hjälp inför valet är en separat vägledning och ersätter inte handledningen hos den leverantör du väljer. Vi kan hjälpa dig att jämföra, men kan inte garantera jobb eller ett visst resultat.", "en": "Kompass does not charge you for this guidance. Arbetsförmedlingen assesses and decides participation in Rusta och matcha. Our pre-choice guidance is separate and does not replace support from your selected provider. We can help compare but cannot guarantee a job or outcome.", "ar": "لا تفرض Kompass عليك رسوماً لهذا الإرشاد. Arbetsförmedlingen تقيم وتقرر المشاركة. إرشادنا منفصل ولا يستبدل دعم مقدم الخدمة المختار. نساعد بالمقارنة ولا نضمن وظيفة أو نتيجة.", "so": "Kompass lacag kaama qaaddo hagiddan. Arbetsförmedlingen ayaa go’aamisa ka qaybgalka. Hagiddeennu waa gaar mana beddelayso adeeg-bixiyaha aad dooratay. Waxaan isbarbardhignaa balse shaqo ma dammaanad qaadno.", "fa": "Kompass برای این راهنمایی هزینه‌ای از شما نمی‌گیرد. Arbetsförmedlingen درباره شرکت تصمیم می‌گیرد. راهنمایی ما جدا و جایگزین حمایت ارائه‌دهنده منتخب نیست. مقایسه می‌کنیم اما شغل یا نتیجه تضمین نمی‌شود.", "uk": "Kompass не бере з вас плату за консультацію. Arbetsförmedlingen визначає участь. Наша допомога перед вибором окрема й не замінює супровід обраного виконавця. Допоможемо порівняти, але не гарантуємо роботу чи результат."}, "official": {"sv": "Läs Arbetsförmedlingens information om Rusta och matcha", "en": "Read Arbetsförmedlingen’s information on Rusta och matcha", "ar": "اقرأ معلومات Arbetsförmedlingen عن البرنامج", "so": "Akhri xogta Arbetsförmedlingen ee barnaamijka", "fa": "اطلاعات Arbetsförmedlingen درباره برنامه را بخوانید", "uk": "Інформація Arbetsförmedlingen про програму"}, "draft": {"sv": "Hej Kompass! Jag vill ha gratis hjälp att jämföra kontor inom Rusta och matcha.\n\nMin ort:\nYrkesområde eller mål:\nHar jag redan ett beslut eller kontor:\nÖnskat kontaktsätt:\n", "en": "Hello Kompass! I would like free help comparing Rusta och matcha offices.\n\nMy location:\nOccupation or goal:\nExisting decision or office:\nPreferred contact method:\n", "ar": "مرحباً Kompass! أريد مساعدة مجانية لمقارنة المكاتب.\n\nالمكان:\nالمهنة أو الهدف:\nهل لدي قرار أو مكتب:\nطريقة التواصل:\n", "so": "Salaan Kompass! Waxaan rabaa hagid bilaash ah oo xafiisyada la isbarbardhigo.\n\nGoobta:\nXirfad ama yool:\nGo’aan ama xafiis jira:\nSida la iigu soo xiriiro:\n", "fa": "سلام Kompass! برای مقایسه دفترها کمک رایگان می‌خواهم.\n\nمحل:\nحرفه یا هدف:\nتصمیم یا دفتر موجود:\nروش تماس:\n", "uk": "Вітаю Kompass! Хочу безкоштовну допомогу з порівнянням офісів.\n\nМісце:\nПрофесія чи мета:\nНаявне рішення чи офіс:\nСпосіб зв’язку:\n"}};
(()=>{
 const root=document.getElementById('kompass-preview');if(!root)return;const picker=root.querySelector('#kompass-language-select'),main=root.querySelector('main'),nav=root.querySelector('nav');const isGuide=location.pathname.endsWith('/rusta-och-matcha.html');let guide;
 const t=key=>rustaTexts[key][picker.value];function el(tag,key){const n=document.createElement(tag);if(key)n.textContent=t(key);return n;}
 function action(){const a=el('a','cta');a.className='action';a.href='kontakta-oss.html?lang='+picker.value;a.addEventListener('click',()=>{try{sessionStorage.setItem('kompassContactDraft',t('draft'));}catch{}});return a;}
 const navLink=el('a','nav');navLink.dataset.rustaNav='true';nav.insertBefore(navLink,nav.querySelector('[data-route=samverkan]'));
 const css=el('style');css.textContent=`#kompass-preview header nav{gap:10px;font-size:12px}#kompass-preview .rusta-callout{margin-top:32px;padding:24px;border:1px solid #a6b7b8;border-radius:8px;background:#f2f7f5}#kompass-preview .hero .rusta-callout{grid-column:1/-1}#kompass-preview .rusta-guide .intro{max-width:900px}#kompass-preview .rusta-guide li{margin-bottom:12px}#kompass-preview .rusta-guide h2{margin-top:32px}@media(max-width:1180px){#kompass-preview header{flex-wrap:wrap;padding:18px 5%}#kompass-preview header .brand{margin-right:auto}#kompass-preview .mobile-menu{display:block}#kompass-preview header nav{display:none;order:4;flex-basis:100%;flex-direction:column;align-items:stretch;white-space:normal;font-size:16px}#kompass-preview header.menu-open nav{display:flex}#kompass-preview header nav a{padding:8px}}`;document.head.append(css);
 function render(){navLink.textContent=({sv:'Våra tjänster',en:'Our services',ar:'خدماتنا',so:'Adeegyadayada',fa:'خدمات ما',uk:'Наші послуги'})[picker.value];navLink.href='tjanster.html?lang='+picker.value;
 for(const callout of root.querySelectorAll('.rusta-callout'))callout.remove();
 for(const host of [root.querySelector('[data-page=start] .hero'),root.querySelector('#kompass-simulatorer')]){if(!host)continue;const box=el('div');box.className='rusta-callout';box.append(el('h3','badge'),el('p','lead'));const a=el('a','nav');a.className='action';a.href=navLink.href;box.append(a);host.append(box);}
 if(!isGuide)return;if(!guide){guide=el('section');guide.className='section rusta-guide';guide.dataset.page='rusta';main.append(guide);}for(const page of main.querySelectorAll('[data-page]'))page.hidden=page!==guide;nav.querySelectorAll('[aria-current]').forEach(a=>a.removeAttribute('aria-current'));navLink.setAttribute('aria-current','page');document.title=t('nav')+' – '+t('badge')+' | Kompass';guide.replaceChildren(el('div','badge'),el('h1','title'));const intro=el('p','lead');intro.className='intro';guide.append(intro,action(),el('h2','whoTitle'),el('p','whoBody'),el('h2','helpTitle'));const grid=el('div');grid.className='grid';for(const [title,body] of [['needs','needsBody'],['compare','compareBody'],['questions','questionsBody']]){const card=el('article');card.className='audience';card.append(el('h3',title),el('p',body));grid.append(card);}guide.append(grid,el('h2','processTitle'));for(let i=1;i<=3;i++)guide.append(el('h3','step'+i),el('p','step'+i+'Body'));guide.append(el('h2','askTitle'));const list=el('ul');for(let i=1;i<=4;i++)list.append(el('li','q'+i));guide.append(list,el('h2','roleTitle'),el('p','roleBody'),action());const official=el('a','official');official.href='https://arbetsformedlingen.se/for-arbetssokande/extra-stod/stod-a-o/rusta-och-matcha';guide.append(el('p'));guide.lastChild.append(official);
 }
 picker.addEventListener('change',render);render();
})();

